package com.metabuild.infrastructure.observability;
import com.metabuild.admin.api.*;import com.metabuild.infrastructure.security.SaTokenSessionControl;import jakarta.servlet.http.*;import java.util.*;import org.springframework.web.method.HandlerMethod;import org.springframework.web.servlet.HandlerInterceptor;
/** 写请求与显式导出的基础设施审计入口，不记录请求体或关键词原文。 */
public final class OperationAuditInterceptor implements HandlerInterceptor {private final SaTokenSessionControl sessions;private final AuditEventWriter writer;public OperationAuditInterceptor(SaTokenSessionControl sessions,AuditEventWriter writer){this.sessions=sessions;this.writer=writer;}@Override public void afterCompletion(HttpServletRequest request,HttpServletResponse response,Object handler,Exception failure){AuditedExport export=handler instanceof HandlerMethod method?method.getMethodAnnotation(AuditedExport.class):null;if((!isWrite(request.getMethod())&&export==null)||request.getRequestURI().startsWith("/api/auth/"))return;UUID actor=null;try{String id=sessions.currentUserId();if(id!=null)actor=UUID.fromString(id);}catch(RuntimeException ignored){/* 登录审计另行记录 */}String path=request.getRequestURI();String resource=path.replaceFirst("^/api/?","").split("/")[0];String operation=export==null?resource+"."+request.getMethod().toLowerCase():export.operation();writer.append(new AuditEvent(actor,operation,resource,request.getMethod(),path,request.getRemoteAddr(),summary(request),rowCount(response),failure==null&&response.getStatus()<400,String.valueOf(request.getAttribute(TraceIdFilter.REQUEST_ATTRIBUTE))));}private static boolean isWrite(String method){return !"GET".equals(method)&&!"HEAD".equals(method)&&!"OPTIONS".equals(method);}private static String summary(HttpServletRequest request){var values=new ArrayList<String>();for(String key:List.of("type","result","startDate","endDate","page","size")){String value=request.getParameter(key);if(value!=null)values.add(key+"="+value);}if(request.getParameter("keyword")!=null)values.add("keyword=<redacted>");return String.join("&",values);}private static long rowCount(HttpServletResponse response){String value=response.getHeader("X-Export-Row-Count");if(value==null)return -1;try{return Long.parseLong(value);}catch(NumberFormatException ignored){return -1;}}}
